import itertools
spans2={8:(0,7),0:(1,9),-9:(9,13),-4:(10,15)}
def predict_pairs(spans, mode='overlap'):
 us=list(spans)
 P=set()
 for u1,u2 in itertools.combinations(us,2):
  a1,b1=spans[u1];a2,b2=spans[u2]
  x1=(2*a1+u1,2*b1+u1);x2=(2*a2+u2,2*b2+u2)
  if mode=='overlap':lo,hi=max(x1[0],x2[0]),min(x1[1],x2[1])
  elif mode=='union':lo,hi=min(x1[0],x2[0]),max(x1[1],x2[1])
  elif mode=='maxstart_maxend':lo,hi=max(x1[0],x2[0]),max(x1[1],x2[1])
  elif mode=='minstart_minend':lo,hi=min(x1[0],x2[0]),min(x1[1],x2[1])
  for r in range(16):
   for c in range(16):
    u=c-r;x=c+r
    if min(u1,u2)<u<max(u1,u2) and lo<=x<=hi:P.add((r,c))
 return P
