def extract_runs(points):
 byu={}
 for r,cs in points.items():
  for c in cs: byu.setdefault(c-r,[]).append((r,c))
 runs=[]
 for u,arr in byu.items():
  arr=sorted(arr)
  cur=[arr[0]]
  for p in arr[1:]:
   if p[0]==cur[-1][0]+1:cur.append(p)
   else:runs.append((u,cur));cur=[p]
  runs.append((u,cur))
 return runs
